const { chromium } = require('D:/repository/门户/node_modules/playwright');
const fs = require('fs');
const OUT = 'D:/repository/门户/test-results/mm-debug';
fs.mkdirSync(OUT, { recursive: true });

const URL = 'http://127.0.0.1:8092/index.html#/market-monitor';

async function snapshot(page, tag) {
  const info = await page.evaluate(() => {
    const q = (s) => document.querySelector(s);
    const box = (el) => {
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) };
    };
    const header = q('.mm-dashboard header');
    const main = q('.mm-dashboard main');
    const sel = q('select[aria-label="监测范围选择"]');
    const btn = header ? header.querySelector('button:last-of-type') : null;
    const cs = btn ? getComputedStyle(btn) : null;
    return {
      header: box(header),
      main: box(main),
      mainChildren: main ? Array.from(main.children).map((c) => ({ tag: c.tagName, cls: c.className.slice(0, 60), ...box(c) })) : [],
      districtValue: sel ? sel.value : null,
      goHomeBtn: { box: box(btn), cls: btn ? btn.className : null, bg: cs ? cs.backgroundColor : null, color: cs ? cs.color : null, border: cs ? cs.borderColor : null },
      bodyScrollHeight: document.body.scrollHeight,
    };
  });
  console.log(tag, JSON.stringify(info));
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 });
  const errs = [];
  page.on('pageerror', (e) => errs.push('PAGEERROR: ' + e.message));
  await page.route('**/fonts.googleapis.com/**', (r) => r.fulfill({ status: 200, contentType: 'text/css', body: '' }));
  await page.route('**/fonts.gstatic.com/**', (r) => r.abort());
  await page.goto(URL, { waitUntil: 'domcontentloaded', timeout: 60000 });
  await page.evaluate(() => document.fonts.ready).catch(() => {});
  await page.waitForTimeout(3000);
  await snapshot(page, 'BEFORE');
  await page.screenshot({ path: OUT + '/before.png' });

  await page.locator('select[aria-label="监测范围选择"]').selectOption({ label: '姑苏区' });
  await page.waitForTimeout(2500);
  await snapshot(page, 'AFTER');
  await page.screenshot({ path: OUT + '/after.png' });
  console.log('ERRORS', JSON.stringify(errs));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

